+    const end = argv.findIndex((w, i) => i > 0 && w.startsWith('-'));
+    const starts = end === -1 ? argv.slice(1) : argv.slice(1, end);
+    const paths = starts.length ? starts : ['.'];
+    const bad = paths.some((p) => unresolvable(p) || !insideWorkspace(p, cwd));
