+
+// Short flag group such as -fu or -df: starts with one dash, not two, and contains one of `letters`.
+const shortGroup = (w: string, letters: string) => w.startsWith('-') && !w.startsWith('--') && w.length > 1 && [...letters].some((l) => w.includes(l));
+
+// Paths that cannot be known before the command runs: variables, or ~user.
+const unresolvable = (p: string) => p.includes('$') || (p.startsWith('~') && p !== '~' && !p.startsWith('~/'));

